#if APP_TESTS
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Threading;
namespace FileCompass {
 internal static class CsvPreviewTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();Window window=null;QuickPreviewPane pane=null;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);checks.Add(label);};try{
   SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));FluentTheme.Ensure();L.ChangeLanguage("cs");
   foreach(char separator in new[]{',',';','\t','|'}){string input="Name"+separator+"Value"+separator+"Note\r\nJiří"+separator+"12,34"+separator+"\"quoted "+separator+" value\"\r\n";if(separator==',')input="Name,Value,Note\r\nJiří,\"12,34\",\"quoted , value\"\r\n";var parsed=CsvDocument.Parse(input);check(parsed.Separator==separator&&parsed.Columns==3&&parsed.Rows.Count==2,"Detect separator outside quoted values: "+(int)separator);check(parsed.Rows[1][1]=="12,34"&&parsed.Rows[1][2].Contains("quoted "),"Preserve decimal commas and quoted separators: "+(int)separator);}
   var model=CsvDocument.Parse("A;B;C\r\n\"line one\r\nline two\";\"a\"\"b\";\r\n");check(model.Rows[1][0]=="line one\r\nline two"&&model.Rows[1][1]=="a\"b"&&model.Rows[1][2]=="","Quoted multiline records, escaped quotes and trailing empty fields");
   check(CsvDocument.Parse("a;b;c").Separator==';',"Detect one-line semicolon CSV without a final newline");check(CsvDocument.Parse("sep=|\rA|B\r1|2").Separator=='|'&&CsvDocument.Parse("sep=|\rA|B\r1|2").Rows.Count==2,"Excel sep directive and CR line endings");check(CsvDocument.Parse("\ufeffsep=;\r\nA;B\r\n1;2").Columns==2,"BOM and sep declaration are omitted from the table");check(CsvDocument.Parse("1,25;2,50\n3,75;4,25").Separator==';',"Headerless decimal-comma data prefers semicolon separators");check(CsvDocument.Parse("A:B\n1:2",':').Columns==2,"Manual colon separator is supported");check(CsvDocument.Parse("A\tB\n1\t2",null,false,"test.tsv").Separator=='\t',"TSV defaults to tab separators");
   model=CsvDocument.Parse("A;B\n1;2\n3;partial",';',true);check(model.Rows.Count==2&&model.Incomplete,"A truncated prefix does not invent a final row");model=CsvDocument.Parse("A;B\n1;\"unfinished");check(model.Rows.Count==1&&model.Incomplete,"An unclosed quoted record is omitted with a warning");model=CsvDocument.Parse("\n\r\nA;B\n\n1;2\n");check(model.Rows.Count==2,"Blank physical lines do not create fake records");check(CsvDocument.Parse("A;B\n1;2;3\n4").Columns==3,"Ragged rows retain their extra columns");
   model=CsvDocument.Parse(String.Join("\n",Enumerable.Repeat("a;b",2500)));check(model.Rows.Count==2000&&model.Limited,"Preview row count is bounded");model=CsvDocument.Parse(String.Join(";",Enumerable.Range(0,150)));check(model.Columns==128&&model.Limited,"Preview column count is bounded");model=CsvDocument.Parse("A;B\n"+new string('x',20000)+";z");check(model.Rows[1][0].Length==16384&&model.Limited,"Individual field length is bounded");
   string csv=Path.Combine(root,"česká-data.csv");File.WriteAllText(csv,"Jméno;Částka;Poznámka\r\nJiří;12,34;\"první řádek\r\ndruhý řádek\"\r\nMíša;0,50;\"uvozovka \"\"a\"\"\"\r\n",new UTF8Encoding(true));var data=PreviewData.Load(csv,Encoding.UTF8,CancellationToken.None);check(!data.IsBinary&&data.Text.Contains("Jiří"),"Local CSV remains decoded text before table rendering");
   string utf16=Path.Combine(root,"unicode.csv");File.WriteAllText(utf16,"Název;Číslo\r\nŽluťoučký;001\r\n",Encoding.Unicode);data=PreviewData.Load(utf16,Encoding.UTF8,CancellationToken.None);check(!data.IsBinary&&CsvDocument.Parse(data.Text).Rows[1][0]=="Žluťoučký","UTF-16 BOM CSV is not misclassified as binary");string cp=Path.Combine(root,"legacy.csv");File.WriteAllText(cp,"Název;Číslo\nŽluťoučký;001\n",Encoding.GetEncoding(1250));data=PreviewData.Load(cp,Encoding.GetEncoding(1250),CancellationToken.None);check(CsvDocument.Parse(data.Text).Rows[1][0]=="Žluťoučký","Explicit Windows-1250 decoding preserves Czech text");
   var details=FileMetadata.Read(csv);check(details.Rows.Any(x=>x.Label==L.Text("details.columns")&&x.Value=="3")&&details.Rows.Any(x=>x.Label==L.Text("details.separator")&&x.Value==";"),"CSV metadata uses the same quote-aware delimiter parser");
   pane=new QuickPreviewPane(delegate{});window=new Window{Content=pane,Width=1080,Height=720,Left=-18000,Top=-18000};window.Show();pane.ShowFile(csv);NavigationTests.Wait(pane.LoadingTask);NavigationTests.Wait(pane.MetadataLoadingTask);check(pane.CsvGrid.IsVisible&&pane.CsvGrid.Columns.Count==3,"Native quick preview renders three actual CSV columns");check(Convert.ToString(pane.CsvGrid.Columns[0].Header)=="Jméno"&&pane.CsvGrid.Items.Count==2,"Header row is displayed as column headers without losing data rows");var first=(string[])pane.CsvGrid.Items[0];check(first[1]=="12,34"&&first[2].Contains("\r\n"),"Grid preserves decimals and multiline cell values");check(pane.CsvGrid.IsReadOnly&&!pane.CsvGrid.CanUserAddRows,"CSV table is read-only");NextStageTests.Draw(window,Path.Combine(root,"csv-table.png"));
   pane.CsvHeader.IsChecked=false;check(pane.CsvGrid.Items.Count==3&&Convert.ToString(pane.CsvGrid.Columns[0].Header)==L.Format("csv.column",1),"Headerless mode retains the first record");pane.CsvSeparator.SelectedIndex=1;check(pane.CsvGrid.Columns.Count!=3,"Manual separator changes the parsed table");pane.CsvSeparator.SelectedIndex=0;pane.CsvHeader.IsChecked=true;check(pane.CsvGrid.Columns.Count==3,"Automatic separator can be restored");
   pane.SetViewMode(PreviewMode.Hex);NavigationTests.Wait(pane.LoadingTask);check(!pane.CsvGrid.IsVisible,"Hex mode hides the table");pane.SetViewMode(PreviewMode.Auto);NavigationTests.Wait(pane.LoadingTask);check(pane.CsvGrid.IsVisible,"Auto mode restores the CSV table");var formatted=FluentUiTests.Children<CheckBox>(pane).First(x=>Convert.ToString(x.Content)==L.Text("preview.formatted"));formatted.IsChecked=false;check(!pane.CsvGrid.IsVisible&&FluentUiTests.Children<TextBox>(pane).Any(x=>x.IsVisible&&x.Text.Contains("Jméno;Částka")),"Raw source text remains available");formatted.IsChecked=true;
   string text=Path.Combine(root,"plain.txt");File.WriteAllText(text,"plain text");pane.ShowFile(text);NavigationTests.Wait(pane.LoadingTask);check(!pane.CsvGrid.IsVisible&&pane.CsvGrid.ItemsSource==null,"Switching files clears the CSV table");pane.ShowFile(utf16);NavigationTests.Wait(pane.LoadingTask);check(pane.CsvGrid.IsVisible&&pane.CsvGrid.Columns.Count==2,"UTF-16 CSV renders in the same table");
   File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(pane!=null)pane.DisposePreview();if(window!=null)window.Close();}}
 }
}
#endif
